#!/usr/bin/env node
/**
 * Copy the default voice container into the package before packing.
 *
 * The `.cfwm` container is 2.5 MB and is generated by the engine build, so it
 * is not committed twice: the package directory only receives a copy at
 * `npm pack` / `npm publish` time (this is the `prepack` hook) and, for local
 * development, the loader can fall back to the workspace copy
 * (`packages/node/../../models/voice-default.cfwm`).
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.join(here, '..');
const source = path.join(packageRoot, '..', '..', 'models', 'voice-default.cfwm');
const target = path.join(packageRoot, 'models', 'voice-default.cfwm');

if (fs.existsSync(target) && fs.statSync(target).size > 0) {
  console.log(`[cleanfield] model already present: ${path.relative(process.cwd(), target)}`);
  process.exit(0);
}

if (!fs.existsSync(source)) {
  console.error(
    `[cleanfield] cannot package without the voice container: ${source} is missing.\n` +
      'Build it with `python tools/build_cfwm.py --blob <weights.bin>` from the workspace root.'
  );
  process.exit(1);
}

fs.mkdirSync(path.dirname(target), { recursive: true });
fs.copyFileSync(source, target);
console.log(
  `[cleanfield] copied ${(fs.statSync(target).size / (1024 * 1024)).toFixed(2)} MiB model into the package`
);
